import{_ as r}from"./chunks/architecture-zh-CN.EQpNaQPQ.js";import{_ as o,o as a,c as t,a2 as l}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"系统架构设计","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 三进程隔离模型","slug":"_1-三进程隔离模型","link":"#_1-三进程隔离模型","children":[{"level":3,"title":"1. 后台索引服务（Lertaro.Service.exe）","slug":"_1-后台索引服务-lertaro-service-exe","link":"#_1-后台索引服务-lertaro-service-exe","children":[]},{"level":3,"title":"2. 用户交互主程序（Lertaro.App）","slug":"_2-用户交互主程序-lertaro-app","link":"#_2-用户交互主程序-lertaro-app","children":[]},{"level":3,"title":"3. 全局键盘钩子与窗口适配进程（Lertaro.Service --hook）","slug":"_3-全局键盘钩子与窗口适配进程-lertaro-service-hook","link":"#_3-全局键盘钩子与窗口适配进程-lertaro-service-hook","children":[]}]},{"level":2,"title":"2. 共享核心层（Shared Core Library）","slug":"_2-共享核心层-shared-core-library","link":"#_2-共享核心层-shared-core-library","children":[]},{"level":2,"title":"3. 插件系统在架构中的定位","slug":"_3-插件系统在架构中的定位","link":"#_3-插件系统在架构中的定位","children":[]}],"relativePath":"zh-CN/dev-guide/architecture.md","filePath":"zh-CN/dev-guide/architecture.md","lastUpdated":1791112464000}'),i={name:"zh-CN/dev-guide/architecture.md"};function c(d,e,s,n,h,p){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="系统架构设计" tabindex="-1">系统架构设计 <a class="header-anchor" href="#系统架构设计" aria-label="Permalink to &quot;系统架构设计&quot;">​</a></h1><p>Lertaro 采用多进程隔离与模块化分层设计，在实现毫秒级检索与窗口集成的同时，保证运行安全与稳定。</p><p><img src="'+r+'" alt="Lertaro 架构图"></p><h2 id="_1-三进程隔离模型" tabindex="-1">1. 三进程隔离模型 <a class="header-anchor" href="#_1-三进程隔离模型" aria-label="Permalink to &quot;1. 三进程隔离模型&quot;">​</a></h2><p>为了避免单个组件异常导致整个系统崩溃，并将 Windows 特权限制在最小范围内，Lertaro 的运行时被明确划分为三个独立的进程：</p><h3 id="_1-后台索引服务-lertaro-service-exe" tabindex="-1">1. 后台索引服务（<code>Lertaro.Service.exe</code>） <a class="header-anchor" href="#_1-后台索引服务-lertaro-service-exe" aria-label="Permalink to &quot;1. 后台索引服务（`Lertaro.Service.exe`）&quot;">​</a></h3><ul><li><strong>运行身份</strong>：以 Windows 系统级 <code>LocalSystem</code> 身份常驻运行的 Windows 服务。</li><li><strong>职责范围</strong>：负责全盘文件索引与增量监听。直接读取 NTFS / ReFS 磁盘底层的 USN 变更日志与 $MFT 主文件表；实时监听 FAT32 / exFAT 磁盘变更；定时抓取并缓存 SMB / NAS 网络共享。</li><li><strong>安全与性能考量</strong>：运行在 SYSTEM 级别使服务无需弹出任何 UAC 提权弹窗即可直接读取原始磁盘卷的元数据；同时通过高性能命名管道向用户态 App 返回检索结果，避免前台 UI 进程持有不必要的全局高权限。</li></ul><h3 id="_2-用户交互主程序-lertaro-app" tabindex="-1">2. 用户交互主程序（<code>Lertaro.App</code>） <a class="header-anchor" href="#_2-用户交互主程序-lertaro-app" aria-label="Permalink to &quot;2. 用户交互主程序（`Lertaro.App`）&quot;">​</a></h3><ul><li><strong>运行身份</strong>：标准 Windows 用户态、Session 隔离的 WPF 前台桌面应用程序。</li><li><strong>职责范围</strong>：承载快速搜索居中浮窗、完整主搜索窗口、设置中心、全局快捷键分发、动作菜单（<code>Ctrl+O</code>）以及 QuickLook 文件即时预览界面。</li><li><strong>IPC 桥梁与 CLI 托管</strong>：通过双向命名管道 <code>LertaroPipe</code> 与后台 Service 通信（<code>Core.Services.Search.SearchService</code> 是 App 侧的客户端）；同时，App 自身还托管了一条面向当前用户的专属命名管道服务（<code>AppSearchPipeService</code>），使外部伴随工具（如 <code>lff</code> 命令行工具）能直接复用 App 已经构建好的内存别名表、插件提供者与网络盘缓存，无需重复初始化。</li></ul><h3 id="_3-全局键盘钩子与窗口适配进程-lertaro-service-hook" tabindex="-1">3. 全局键盘钩子与窗口适配进程（<code>Lertaro.Service --hook</code>） <a class="header-anchor" href="#_3-全局键盘钩子与窗口适配进程-lertaro-service-hook" aria-label="Permalink to &quot;3. 全局键盘钩子与窗口适配进程（`Lertaro.Service --hook`）&quot;">​</a></h3><ul><li><strong>运行身份</strong>：由后台服务拉起的独立辅助进程。它<strong>仅在登录账户是真正的管理员时才提权启动</strong>；否则它以当前用户自己的令牌运行，因此下文的权限突破只在这样的机器上可用。</li><li><strong>职责范围</strong>：托管低级全局键盘钩子（Low-Level Keyboard Hook）与鼠标全局监听。</li><li><strong>UIPI 权限突破与崩溃隔离</strong>：在 Windows 安全体系中，低完整性级别的用户态进程无法向以管理员身份运行的高权限窗口发送窗口消息或模拟输入（UIPI 隔离）。通过在该 Hook 进程中运行窗口集成适配器（<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a>），只要钩子进程是以提权身份启动的，Lertaro 就能读取并操作由管理员身份启动的文件资源管理器、Total Commander 或第三方对话框。同时，即使底层钩子因第三方游戏的反作弊模块产生异常，也不会影响主 App 进程的正常运行。</li></ul><h2 id="_2-共享核心层-shared-core-library" tabindex="-1">2. 共享核心层（Shared Core Library） <a class="header-anchor" href="#_2-共享核心层-shared-core-library" aria-label="Permalink to &quot;2. 共享核心层（Shared Core Library）&quot;">​</a></h2><p><code>Lertaro.Core</code> 是被 Service、App 和 Hook 进程同时引用的基础类库，主要包含以下关键模块：</p><ul><li><strong>自研 fzf 模糊匹配引擎（<code>Core/SearchIndex/Fzf/*</code>）</strong>：复刻并优化了知名 <code>fzf</code> 算法的跳跃字符模糊匹配、子串分段与字符级高亮计算，配合 <code>SearchQueryParser</code> 实现盘符定向与路径模式切分。</li><li><strong>列式内存索引（<code>Core/IndexV2/*</code>）</strong>：采用内存映射列式快照（Columnar Snapshot）与内存增量覆盖层（Delta Overlay），实现亿级文件条目的亚毫秒级检索。</li><li><strong>二进制 IPC 通信契约</strong>：定义了 <code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等标准二进制数据协议，确保多进程间零拷贝高效序列化。</li><li><strong>统一多进程日志系统（<code>Logger</code>）</strong>：分别输出至 <code>service.log</code>、<code>app.log</code> 与 <code>hook.log</code>，并由 App 的设置中心日志查看器统一代理读取与呈现。</li></ul><h2 id="_3-插件系统在架构中的定位" tabindex="-1">3. 插件系统在架构中的定位 <a class="header-anchor" href="#_3-插件系统在架构中的定位" aria-label="Permalink to &quot;3. 插件系统在架构中的定位&quot;">​</a></h2><p>所有第三方及内置插件均基于 <code>Lertaro.PluginSdk</code> 构建，由 <code>Lertaro.App</code> 进程在启动时自动反射扫描并加载：</p><ul><li><strong>零特权直接通信</strong>：插件自身的代码与加载它的进程同进程运行——通常是 App，但 Service 也会加载的两种类型见下一条。插件不会自行跨越进程边界，因此需要自定义目录索引的插件会通过 <code>DirectoryIndexerService</code> 把这项工作委托给宿主，而不是自己去遍历磁盘。</li><li><strong>选择性双重加载</strong>：搜索源、动作与界面扩展仅在 App 进程中运行。有三类组件会被同时加载到其他进程：窗口与文件对话框适配器（<code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code>）进入 Hook 进程以处理跨完整性级别的窗口自动化；<code>IAliasProvider</code> 与 <code>ITranslationProvider</code> 还会由 <strong>Service</strong> 额外加载（<code>ServicePluginLoader</code>），因为索引器要构建别名行，需要与界面呈现一致的转写与命名。</li></ul>',17)])])}const S=o(i,[["render",c]]);export{_ as __pageData,S as default};
